/**
 * Calendar-period arithmetic for subscriptions.
 *
 * A monthly period ends on the same UTC day of the next month, or on that
 * month's last day when it has no such day. An annual period is the same rule
 * twelve months later (29 February lands on 28 February). The next period
 * starts exactly where the previous one ended, so a clamped day carries
 * forward.
 */
import { getPlanLimits } from "@/config/plan-limits";
import type { BillingInterval, PlanId } from "@/types/billing";

const DAY_MS = 24 * 60 * 60 * 1000;

export function addBillingInterval(start: Date, interval: BillingInterval): Date {
  const months = interval === "annual" ? 12 : 1;
  const monthIndex = start.getUTCMonth() + months;
  const year = start.getUTCFullYear() + Math.floor(monthIndex / 12);
  const month = ((monthIndex % 12) + 12) % 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  const day = Math.min(start.getUTCDate(), lastDay);

  return new Date(
    Date.UTC(
      year,
      month,
      day,
      start.getUTCHours(),
      start.getUTCMinutes(),
      start.getUTCSeconds(),
      start.getUTCMilliseconds(),
    ),
  );
}

/** Whole days in the period, rounded, and never zero. */
export function periodLengthDays(start: Date, end: Date): number {
  return Math.max(1, Math.round((end.getTime() - start.getTime()) / DAY_MS));
}

/**
 * Whole or started days from `at` until `end`. Fourteen days and twenty-two
 * hours count as fifteen. Nothing remains once `end` has been reached.
 */
export function daysRemaining(at: Date, end: Date): number {
  const remaining = end.getTime() - at.getTime();
  if (remaining <= 0) return 0;
  return Math.ceil(remaining / DAY_MS);
}

/** Full charge for one period, in cents. */
export function fullPeriodCents(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  const months = interval === "annual" ? 12 : 1;
  return getPlanLimits(plan).priceCentsPerSeatMonthly * seats * months;
}

/**
 * Scales a full-period amount by the days still left in the period, rounded
 * down to whole cents.
 */
export function prorateCents(
  fullAmountCents: number,
  periodStart: Date,
  periodEnd: Date,
  at: Date,
): number {
  if (fullAmountCents <= 0) return 0;
  const left = daysRemaining(at, periodEnd);
  if (left === 0) return 0;
  const span = periodLengthDays(periodStart, periodEnd);
  return Math.floor((fullAmountCents * left) / span);
}

