/** A plan change ends the trial: the org has made a deliberate choice. */
export async function updateSubscriptionPlan(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
  period?: { start: IsoTimestamp; end: IsoTimestamp },
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(subscriptions)
    .set({
      plan,
      interval,
      status: "active",
      updatedAt: stamp,
      ...(period
        ? { currentPeriodStart: period.start, currentPeriodEnd: period.end }
        : {}),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  syncOrgPlan(orgId, plan, stamp);
  return toSubscription(row);
}

/** Moves the current period forward without touching plan or seats. */
export async function advancePeriod(
  orgId: OrgId,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(subscriptions)
    .set({
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
      updatedAt: stamp,
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/**
 * Cancellation has come due: the workspace is on the free plan, active, with
 * a monthly period that starts at the cancellation instant.
 */
export async function settleCancellation(
  orgId: OrgId,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(subscriptions)
    .set({
      plan: "free",
      interval: "monthly",
      status: "active" satisfies SubscriptionStatus,
      cancelAt: null,
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
      updatedAt: stamp,
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  syncOrgPlan(orgId, "free", stamp);
  return toSubscription(row);
}

/** Every subscription whose workspace has not been archived. */
export async function listSubscriptionsForBilling(): Promise<
  readonly Subscription[]
> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(isNull(organizations.archivedAt))
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}

function syncOrgPlan(orgId: OrgId, plan: PlanId, stamp: IsoTimestamp): void {
  getDb()
    .update(organizations)
    .set({ plan, updatedAt: stamp })
    .where(eq(organizations.id, orgId))
    .run();
}

