  );

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const at = new Date();
  const leavingFree = current.plan === "free" && input.plan !== "free";
  const duringTrial = current.status === "trialing";
  const period =
    leavingFree && !duringTrial
      ? {
          start: toIsoTimestamp(at),
          end: toIsoTimestamp(addBillingInterval(at, input.interval)),
        }
      : undefined;

  const subscription = await subscriptionRepo.updateSubscriptionPlan(
    input.orgId,
    input.plan,
    input.interval,
    period,
  );

  if (duringTrial) {
    // Choosing a plan during a trial keeps that period and is not invoiced.
  } else if (leavingFree) {
    await publishInvoice({
      orgId: input.orgId,
      amountCents: fullPeriodCents(input.plan, current.seats, input.interval),
      periodStart: subscription.currentPeriodStart,
      periodEnd: subscription.currentPeriodEnd,
      actorId: actor.userId,
      occurredAt: toIsoTimestamp(at),
    });
  } else if (
    current.status === "active" &&
    current.plan !== "free" &&
    input.plan !== "free"
  ) {
    const difference =
      getPlanLimits(input.plan).priceCentsPerSeatMonthly -
      getPlanLimits(current.plan).priceCentsPerSeatMonthly;
    if (difference > 0) {
      const months = current.interval === "annual" ? 12 : 1;
      const full = difference * current.seats * months;
      await publishInvoice({
        orgId: input.orgId,
        amountCents: prorateCents(
          full,
          parseIso(current.currentPeriodStart),
          parseIso(current.currentPeriodEnd),
          at,
        ),
        periodStart: current.currentPeriodStart,
        periodEnd: current.currentPeriodEnd,
        actorId: actor.userId,
        occurredAt: toIsoTimestamp(at),
      });
    }
  }

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: current.plan,
    to: input.plan,
  });

  return subscription;
}

