 *
 * Must call (do not reimplement): emit, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { addBillingInterval, fullPeriodCents } from "@/lib/billing-period";
import { parseIso } from "@/lib/date";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { publishInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";

const logger = createLogger("billing-renewal-job");

/** A hard stop so a malformed period cannot spin forever. */
const MAX_PERIODS = 240;

export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listSubscriptionsForBilling();

    for (const subscription of subscriptions) {
      try {
        const changed = await renewOne(subscription, now);
        if (changed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.warn("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function renewOne(
  initial: Subscription,
  now: Date,
): Promise<boolean> {
  let subscription = initial;
  let changed = false;
  const nowMs = now.getTime();
  const occurredAt = toIsoTimestamp(now);

  if (subscription.status === "canceled") {
    if (
      subscription.cancelAt === null ||
      parseIso(subscription.cancelAt).getTime() > nowMs
    ) {
      return false;
    }

    const from = subscription.plan;
    const start = parseIso(subscription.cancelAt);
    const end = addBillingInterval(start, "monthly");
    subscription = await subscriptionRepo.settleCancellation(
      subscription.orgId,
      toIsoTimestamp(start),
      toIsoTimestamp(end),
    );
    changed = true;

    await emit("billing.plan_changed", {
      orgId: subscription.orgId,
      actorId: null,
      occurredAt,
      from,
      to: "free",
    });
  }

  if (subscription.status === "trialing" || subscription.status === "past_due") {
    return changed;
  }

  if (subscription.status !== "active") return changed;

  let periods = 0;
  while (parseIso(subscription.currentPeriodEnd).getTime() <= nowMs) {
    periods += 1;
    if (periods > MAX_PERIODS) {
      throw new Error(`Subscription ${subscription.orgId} did not catch up`);
    }

    const start = parseIso(subscription.currentPeriodEnd);
    const end = addBillingInterval(start, subscription.interval);
    const amount = fullPeriodCents(
      subscription.plan,
      subscription.seats,
      subscription.interval,
    );
    // Touch the plan table so a mis-priced plan fails here rather than later.
    getPlanLimits(subscription.plan);

    const periodStart = toIsoTimestamp(start);
    const periodEnd = toIsoTimestamp(end);
    subscription = await subscriptionRepo.advancePeriod(
      subscription.orgId,
      periodStart,
      periodEnd,
    );
    changed = true;

    if (subscription.plan !== "free" && amount > 0) {
      await publishInvoice({
        orgId: subscription.orgId,
        amountCents: amount,
        periodStart,
        periodEnd,
        actorId: null,
        occurredAt,
      });
    }
  }

  return changed;
}
