import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { subscribe } from "@/lib/event-bus";
import { getDb, subscriptions } from "@/server/db";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { changePlan, updateSeats } from "@/server/services/billing-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import { addBillingInterval, prorateCents } from "@/lib/billing-period";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

async function activate(orgId: string, start: string, end: string, seats = 2) {
  getDb()
    .update(subscriptions)
    .set({
      status: "active",
      seats,
      currentPeriodStart: start,
      currentPeriodEnd: end,
      cancelAt: null,
    })
    .where(eq(subscriptions.orgId, orgId))
    .run();
}

describe("billing renewal", () => {
  it("renews three elapsed months and is replay-safe", async () => {
    const tenant = await createTenant("renew-three", "starter");
    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "starter", "monthly");
    const start = new Date("2026-01-31T15:00:00.000Z");
    let end = addBillingInterval(start, "monthly");
    await activate(
      tenant.org.id,
      start.toISOString(),
      end.toISOString(),
      2,
    );
    const now = new Date("2026-05-15T15:00:00.000Z");
    const events: unknown[] = [];
    const off = subscribe("billing.invoice_issued", (payload) => {
      events.push(payload);
    });

    await runBillingRenewalJob(now);
    await runBillingRenewalJob(now);
    off();

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(3);
    expect(events).toHaveLength(3);
    expect(invoices.every((invoice) => invoice.paidAt === null && invoice.currency === "usd")).toBe(true);
    expect(invoices.every((invoice) => invoice.amountCents === 900 * 2)).toBe(true);
    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(sub?.currentPeriodEnd! > now.toISOString()).toBe(true);
    expect(end.toISOString()).toBe("2026-02-28T15:00:00.000Z");

    const activity = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["billing.invoice_issued"],
      limit: 25,
      cursor: null,
    });
    expect(activity.items).toHaveLength(3);
    expect(activity.items[0]?.subjectKind).toBe("subscription");
    expect(activity.items[0]?.subjectId).toBe(tenant.org.id);

    const notes = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(notes.items.filter((n) => n.kind === "invoice_issued")).toHaveLength(3);
  });

  it("ends a cancellation without invoicing and ignores it before the date", async () => {
    const tenant = await createTenant("cancel-me", "growth");
    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "growth", "annual");
    await activate(tenant.org.id, "2026-01-01T00:00:00.000Z", "2027-01-01T00:00:00.000Z", 3);
    await subscriptionRepo.cancelSubscription(tenant.org.id, "2026-06-01T00:00:00.000Z");

    await runBillingRenewalJob(new Date("2026-05-01T00:00:00.000Z"));
    let sub = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(sub?.plan).toBe("growth");
    expect(sub?.status).toBe("canceled");

    const events: unknown[] = [];
    const off = subscribe("billing.plan_changed", (p) => events.push(p));
    await runBillingRenewalJob(new Date("2026-06-01T00:00:00.000Z"));
    await runBillingRenewalJob(new Date("2026-06-01T00:00:00.000Z"));
    off();
    sub = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(sub).toMatchObject({
      plan: "free",
      status: "active",
      interval: "monthly",
      cancelAt: null,
      currentPeriodStart: "2026-06-01T00:00:00.000Z",
    });
    expect(sub?.currentPeriodEnd).toBe("2026-07-01T00:00:00.000Z");
    expect(events).toHaveLength(1);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
  });

  it("prorates an upgrade and added seats, and not a downgrade or a trial", async () => {
    const tenant = await createTenant("prorate", "starter");
    const start = new Date("2026-03-01T00:00:00.000Z");
    const end = new Date("2026-04-01T00:00:00.000Z");
    await activate(tenant.org.id, start.toISOString(), end.toISOString(), 2);
    const at = new Date("2026-03-17T02:00:00.000Z");
    vi.useFakeTimers();
    vi.setSystemTime(at);
    await changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "monthly",
    });
    const full = (1900 - 900) * 2 * 1;
    const expected = prorateCents(full, start, end, at);
    let invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]?.amountCents).toBe(expected);
    expect(invoices[0]?.periodStart).toBe(start.toISOString());

    await updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 4 });
    const seatCharge = prorateCents(1900 * 2, start, end, at);
    invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.map((i) => i.amountCents).sort()).toEqual([expected, seatCharge].sort());

    await updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 3 });
    invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(2);

    const trial = await createTenant("trial-change", "starter");
    await changePlan(trial.actors.owner, {
      orgId: trial.org.id,
      plan: "growth",
      interval: "annual",
    });
    expect(await invoiceRepo.listInvoices(trial.org.id)).toHaveLength(0);
    const trialSub = await subscriptionRepo.findSubscription(trial.org.id);
    expect(trialSub?.status).toBe("active");
    expect(trialSub?.plan).toBe("growth");

    const free = await createTenant("free-up", "free");
    await changePlan(free.actors.owner, {
      orgId: free.org.id,
      plan: "starter",
      interval: "annual",
    });
    const freeInvoices = await invoiceRepo.listInvoices(free.org.id);
    expect(freeInvoices).toHaveLength(1);
    expect(freeInvoices[0]?.amountCents).toBe(900 * 1 * 12);
    vi.useRealTimers();
  });
});

